/* ============================================================
   API — backend real (SQLite via node:sqlite). Sem mais dados mockados:
   tudo abaixo é carregado do servidor.
   ============================================================ */
const API_BASE = '';
let AUTH_TOKEN = null;
try { AUTH_TOKEN = localStorage.getItem('trifarmas_token'); } catch(e) {}

async function apiFetch(path, options={}){
  const headers = Object.assign({'Content-Type':'application/json'}, options.headers||{});
  if(AUTH_TOKEN) headers['Authorization'] = 'Bearer ' + AUTH_TOKEN;
  let res;
  try{
    res = await fetch(API_BASE + path, Object.assign({}, options, {headers}));
  }catch(networkErr){
    // fetch nem conseguiu chegar no servidor — quase sempre é o backend não estar rodando
    throw new Error('Não consegui falar com o servidor. Confira se você rodou "node server.js" e se está acessando http://localhost:3000 (não o arquivo index.html direto).');
  }
  let data = {};
  let parseFailed = false;
  try { data = await res.json(); } catch(e) { parseFailed = true; }
  if(!res.ok){
    let msg = data.error;
    if(!msg && parseFailed){
      msg = `O servidor respondeu, mas não em JSON (HTTP ${res.status}). Isso costuma acontecer quando o site está sendo aberto por um servidor diferente do "node server.js" (ex: abrindo o index.html direto, ou outro servidor estático), que não conhece as rotas /api/...`;
    }
    const err = new Error(msg || `Erro do servidor (HTTP ${res.status}).`);
    err.status = res.status;
    throw err;
  }
  return data;
}

const MAP_SIZE = 900;
const MAP_USER = {x:450, y:450};

let PHARMACIES = [];   // vem de GET /api/pharmacies
let ALL_MEDS = [];     // vem de GET /api/medicines (lista completa, sem filtro)
let CATEGORIES = [];   // vem junto com /api/medicines
let REWARDS = [];      // vem de GET /api/rewards

let state = {
  user:null,
  theme:'light',
  activeTab:'home',
  activeCat:'Todos',
  reminders:[],
  orders:[],
  calMonth: new Date().getMonth(),
  calYear: new Date().getFullYear(),
  calSelectedDay: new Date().getDate(),
};

/* carrega os dados que não mudam por usuário (farmácias, catálogo, recompensas) */
async function loadStaticData(){
  const [pharmRes, medRes, rewardRes] = await Promise.all([
    apiFetch('/api/pharmacies'),
    apiFetch('/api/medicines'),
    apiFetch('/api/rewards'),
  ]);
  PHARMACIES = pharmRes.pharmacies.map(p=>({id:p.id, name:p.name, dist:p.dist_km, x:p.map_x, y:p.map_y}));
  ALL_MEDS = medRes.medicines;
  CATEGORIES = medRes.categories;
  REWARDS = rewardRes.rewards;
}

/* ============================================================
   AUTH
   ============================================================ */
function showView(name){
  document.getElementById('view-login').classList.toggle('hidden', name!=='login');
  document.getElementById('view-signup').classList.toggle('hidden', name!=='signup');
  document.getElementById('login-error').classList.add('hidden');
}

function previewAvatar(input, targetId, isSettings){
  if(!input.files || !input.files[0]) return;
  const reader = new FileReader();
  reader.onload = e => {
    document.getElementById(targetId).src = e.target.result;
    if(isSettings && state.user){
      state.user.avatar = e.target.result;
      document.getElementById('sidebar-avatar').src = e.target.result;
    }
  };
  reader.readAsDataURL(input.files[0]);
}

async function doLogin(){
  const email = document.getElementById('login-email').value.trim();
  const pass = document.getElementById('login-pass').value;
  const err = document.getElementById('login-error');
  err.classList.add('hidden');
  if(!email || !pass){
    err.textContent = 'Preencha e-mail e senha para continuar.';
    err.classList.remove('hidden');
    return;
  }
  try{
    const data = await apiFetch('/api/auth/login', {method:'POST', body: JSON.stringify({email, password: pass})});
    AUTH_TOKEN = data.token;
    try { localStorage.setItem('trifarmas_token', AUTH_TOKEN); } catch(e) {}
    state.user = data.user;
    await enterApp();
  }catch(e){
    err.textContent = e.message;
    err.classList.remove('hidden');
  }
}

async function doSignup(){
  const name = document.getElementById('signup-name').value.trim();
  const email = document.getElementById('signup-email').value.trim();
  const pass = document.getElementById('signup-pass').value;
  if(!name || !email || !pass){ showToast('Preencha todos os campos.'); return; }
  const customAvatar = document.getElementById('signup-avatar-preview').src;
  try{
    const body = {name, email, password: pass};
    if(customAvatar && customAvatar.startsWith('data:')) body.avatar = customAvatar;
    const data = await apiFetch('/api/auth/signup', {method:'POST', body: JSON.stringify(body)});
    AUTH_TOKEN = data.token;
    try { localStorage.setItem('trifarmas_token', AUTH_TOKEN); } catch(e) {}
    state.user = data.user;
    showToast('Conta criada! Você ganhou 50 pontos de boas-vindas 🎉');
    await enterApp();
  }catch(e){
    showToast(e.message);
  }
}

async function doLogout(){
  try{ await apiFetch('/api/auth/logout', {method:'POST'}); }catch(e){}
  AUTH_TOKEN = null;
  try { localStorage.removeItem('trifarmas_token'); } catch(e) {}
  state.user = null;
  document.getElementById('app').classList.add('hidden');
  showView('login');
  document.getElementById('login-pass').value='';
}

async function enterApp(){
  await loadStaticData();
  document.getElementById('view-login').classList.add('hidden');
  document.getElementById('view-signup').classList.add('hidden');
  document.getElementById('app').classList.remove('hidden');
  document.getElementById('home-greeting').textContent = `Olá, ${state.user.name.split(' ')[0]}! Pesquise um remédio e veja as farmácias mais perto de você.`;
  document.getElementById('settings-avatar').src = state.user.avatar || '';
  document.getElementById('settings-name').value = state.user.name;
  document.getElementById('settings-email').value = state.user.email;
  document.getElementById('sidebar-avatar').src = state.user.avatar || '';
  document.getElementById('sidebar-name').textContent = state.user.name;
  buildChips();
  updatePointsUI();
  switchTab('home');
}

/* tenta reaproveitar uma sessão salva (token no localStorage) ao abrir o app */
async function tryAutoLogin(){
  if(!AUTH_TOKEN) return false;
  try{
    const data = await apiFetch('/api/me');
    state.user = data.user;
    await enterApp();
    return true;
  }catch(e){
    AUTH_TOKEN = null;
    try { localStorage.removeItem('trifarmas_token'); } catch(er) {}
    return false;
  }
}

/* ============================================================
   NAV
   ============================================================ */
function buildNav(){
  const sidebar = document.getElementById('sidebar-nav');
  const bottom = document.getElementById('bottom-nav');
  sidebar.innerHTML = NAV_ITEMS.map(it=>`
    <button class="nav-item" data-tab="${it.id}" onclick="switchTab('${it.id}')">${it.icon}<span>${it.label}</span></button>
  `).join('') + `
    <div class="sidebar-foot" onclick="switchTab('settings')" style="cursor:pointer;">
      <img id="sidebar-avatar" src="" alt="">
      <div>
        <p class="name" id="sidebar-name">—</p>
        <p class="role">Ver perfil</p>
      </div>
    </div>
  `;
  bottom.innerHTML = NAV_ITEMS.map(it=>{
    if(it.center){
      return `<button class="bn-scan" data-tab="${it.id}" onclick="switchTab('${it.id}')">${it.icon}</button>`;
    }
    return `<button class="bn-item" data-tab="${it.id}" onclick="switchTab('${it.id}')">${it.icon}<span>${it.label}</span></button>`;
  }).join('');
}

function switchTab(id){
  state.activeTab = id;
  document.querySelectorAll('.content-inner > section').forEach(s=>s.classList.add('hidden'));
  document.getElementById('tab-'+id).classList.remove('hidden');
  document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active', b.dataset.tab===id));
  document.querySelectorAll('.bn-item').forEach(b=>b.classList.toggle('active', b.dataset.tab===id));

  if(id==='map') renderMap();
  if(id==='scanner') backToScannerChooser();
  else stopScanner();
  if(id==='calendar') renderCalendar();
  if(id==='orders') renderOrders();
  if(id==='points') renderPoints();
  if(id==='home') renderResults();
}

