/* ---- interação: arrastar e zoom, estilo Google Maps ---- */
const mapState = {x:0, y:0, scale:1, minScale:0.55, maxScale:2.4};
let mapInteractionReady = false;
let mapDrag = null;
let mapPinch = null;

/* garante que o zoom mínimo nunca deixe o mapa menor que a área visível
   (senão sobra fundo vazio nas bordas ao afastar o zoom) */
function updateMinScale(){
  const vp = document.getElementById('map-viewport');
  if(!vp || !vp.clientWidth) return;
  mapState.minScale = Math.max(0.55, (Math.max(vp.clientWidth, vp.clientHeight) / MAP_SIZE) * 1.03);
  if(mapState.scale < mapState.minScale) mapState.scale = mapState.minScale;
}

function clampMapState(){
  const vp = document.getElementById('map-viewport');
  if(!vp) return;
  const vw = vp.clientWidth, vh = vp.clientHeight;
  const size = MAP_SIZE * mapState.scale;
  // trava rígida: a borda do mapa nunca pode ficar visível dentro da janela
  const minX = Math.min(0, vw - size);
  const minY = Math.min(0, vh - size);
  mapState.x = Math.max(minX, Math.min(0, mapState.x));
  mapState.y = Math.max(minY, Math.min(0, mapState.y));
}

function applyMapTransform(){
  const canvas = document.getElementById('map-canvas');
  if(!canvas) return;
  clampMapState();
  canvas.style.transform = `translate(${mapState.x}px, ${mapState.y}px) scale(${mapState.scale})`;
}

function zoomMapBy(factor, pivotX, pivotY){
  const vp = document.getElementById('map-viewport');
  if(!vp) return;
  const rect = vp.getBoundingClientRect();
  const px = pivotX!=null ? pivotX-rect.left : rect.width/2;
  const py = pivotY!=null ? pivotY-rect.top : rect.height/2;
  const newScale = Math.max(mapState.minScale, Math.min(mapState.maxScale, mapState.scale*factor));
  const realFactor = newScale/mapState.scale;
  mapState.x = px - (px-mapState.x)*realFactor;
  mapState.y = py - (py-mapState.y)*realFactor;
  mapState.scale = newScale;
  applyMapTransform();
}

function setMapView(centerX, centerY, scale, animated){
  const vp = document.getElementById('map-viewport');
  const canvas = document.getElementById('map-canvas');
  if(!vp || !canvas) return;
  mapState.scale = Math.max(mapState.minScale, Math.min(mapState.maxScale, scale));
  mapState.x = vp.clientWidth/2 - centerX*mapState.scale;
  mapState.y = vp.clientHeight/2 - centerY*mapState.scale;
  canvas.style.transition = animated ? 'transform .45s ease' : 'none';
  applyMapTransform();
  if(animated) setTimeout(()=>{ canvas.style.transition='none'; }, 460);
}

/* enquadra automaticamente todas as farmácias + o usuário na tela, com folga
   (igual ao "fit bounds" que o Google Maps faz ao mostrar vários resultados) */
function fitMapToMarkers(animated){
  const vp = document.getElementById('map-viewport');
  if(!vp) return;
  updateMinScale();
  const pts = [MAP_USER, ...PHARMACIES];
  const minX = Math.min(...pts.map(p=>p.x)), maxX = Math.max(...pts.map(p=>p.x));
  const minY = Math.min(...pts.map(p=>p.y)), maxY = Math.max(...pts.map(p=>p.y));
  const padX = 90, padTop = 130, padBottom = 60; // padTop maior: pino + etiqueta desenham para cima do ponto
  const boundsW = (maxX-minX) + padX*2;
  const boundsH = (maxY-minY) + padTop + padBottom;
  const scale = Math.min(vp.clientWidth/boundsW, vp.clientHeight/boundsH);
  const centerX = (minX+maxX)/2;
  const centerY = (minY+maxY)/2 + (padTop-padBottom)/2;
  setMapView(centerX, centerY, scale, animated);
}

/* centraliza e aproxima na localização do usuário (botão de mira) */
function centerMapOnUser(animated){
  const vp = document.getElementById('map-viewport');
  if(!vp) return;
  const scale = Math.max(mapState.scale, Math.min(mapState.maxScale, 1.3));
  setMapView(MAP_USER.x, MAP_USER.y, scale, animated);
}

function setupMapInteraction(){
  if(mapInteractionReady) return;
  mapInteractionReady = true;
  const vp = document.getElementById('map-viewport');

  window.addEventListener('resize', ()=>{
    if(state.activeTab!=='map') return;
    updateMinScale();
    applyMapTransform();
  });

  vp.addEventListener('pointerdown', (e)=>{
    vp.setPointerCapture(e.pointerId);
    vp.classList.add('dragging');
    mapDrag = {startX:e.clientX, startY:e.clientY, origX:mapState.x, origY:mapState.y};
  });
  vp.addEventListener('pointermove', (e)=>{
    if(!mapDrag) return;
    mapState.x = mapDrag.origX + (e.clientX-mapDrag.startX);
    mapState.y = mapDrag.origY + (e.clientY-mapDrag.startY);
    applyMapTransform();
  });
  const endDrag = (e)=>{
    if(mapDrag){ mapDrag=null; vp.classList.remove('dragging'); }
  };
  vp.addEventListener('pointerup', endDrag);
  vp.addEventListener('pointercancel', endDrag);
  vp.addEventListener('pointerleave', endDrag);

  vp.addEventListener('wheel', (e)=>{
    e.preventDefault();
    const factor = e.deltaY < 0 ? 1.14 : 1/1.14;
    zoomMapBy(factor, e.clientX, e.clientY);
  }, {passive:false});

  // pinça (zoom com dois dedos) no touch
  vp.addEventListener('touchstart', (e)=>{
    if(e.touches.length===2){
      mapDrag = null;
      const [a,b] = e.touches;
      mapPinch = {
        dist: Math.hypot(a.clientX-b.clientX, a.clientY-b.clientY),
        cx: (a.clientX+b.clientX)/2, cy: (a.clientY+b.clientY)/2
      };
    }
  }, {passive:true});
  vp.addEventListener('touchmove', (e)=>{
    if(e.touches.length===2 && mapPinch){
      e.preventDefault();
      const [a,b] = e.touches;
      const newDist = Math.hypot(a.clientX-b.clientX, a.clientY-b.clientY);
      const factor = newDist/mapPinch.dist;
      zoomMapBy(factor, mapPinch.cx, mapPinch.cy);
      mapPinch.dist = newDist;
    }
  }, {passive:false});
  vp.addEventListener('touchend', ()=>{ mapPinch=null; });

  document.getElementById('map-zoom-in').addEventListener('click', ()=> zoomMapBy(1.3));
  document.getElementById('map-zoom-out').addEventListener('click', ()=> zoomMapBy(1/1.3));
  document.getElementById('map-locate').addEventListener('click', ()=> centerMapOnUser(true));
}

function renderMap(){
  const canvas = document.getElementById('map-canvas');
  const bestId = PHARMACIES.reduce((a,b)=> a.dist<b.dist ? a : b).id;

  const pins = PHARMACIES.map(p=>`
      <div class="map-pin ${p.id===bestId?'best':''}" style="left:${p.x}px; top:${p.y}px;" onclick="pinInfo('${p.id}')">
        <div class="pin-body"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4"><path d="M11 3h2v6h6v2h-6v10h-2V11H5V9h6V3z"/></svg></div>
        <div class="pin-label">${p.name.split(' ')[0]} ${p.name.split(' ')[1]||''} · ${p.dist}km</div>
      </div>
  `).join('');

  canvas.innerHTML = `
    ${buildCityMap()}
    <div class="map-pulse" style="left:${MAP_USER.x}px;top:${MAP_USER.y}px;"></div>
    <div class="map-you" style="left:${MAP_USER.x}px;top:${MAP_USER.y}px;"></div>
    <div class="map-you-label" style="left:${MAP_USER.x}px;top:${MAP_USER.y}px;">Você</div>
    ${pins}
  `;

  setupMapInteraction();
  fitMapToMarkers(false);
}
function pinInfo(id){
  const p = pharmacyById(id);
  showToast(`${p.name} — a ${p.dist.toFixed(1)} km de você`);
}

/* ============================================================
   SCANNER
   ============================================================ */
let scannerStream = null;
let scannerMode = null; // 'price' ou 'bula'

function backToScannerChooser(){
  stopScanner();
  scannerMode = null;
  document.getElementById('scanner-chooser').classList.remove('hidden');
  document.getElementById('scanner-camera-step').classList.add('hidden');
  document.getElementById('scanner-bula-result').classList.add('hidden');
}

function selectScannerMode(mode){
  scannerMode = mode;
  document.getElementById('scanner-chooser').classList.add('hidden');
  document.getElementById('scanner-bula-result').classList.add('hidden');
  document.getElementById('scanner-camera-step').classList.remove('hidden');

  const isBula = mode === 'bula';
  document.getElementById('scanner-camera-title').textContent = isBula ? 'Escanear bula' : 'Escanear remédio';
  document.getElementById('scanner-camera-sub').textContent = isBula
    ? 'Aponte a câmera para o texto da bula, bem iluminado e sem dobras.'
    : 'Aponte a câmera para a caixa ou o código de barras.';
  document.getElementById('scanner-capture-btn').textContent = isBula ? 'Capturar bula' : 'Capturar agora';
  document.getElementById('scanner-fallback-price').classList.toggle('hidden', isBula);
  document.getElementById('scanner-fallback-bula').classList.toggle('hidden', !isBula);

  startScanner();
}

async function startScanner(){
  const video = document.getElementById('scanner-video');
  const status = document.getElementById('scanner-status');
  if(scannerMode==='price') buildScannerMockList();
  try{
    scannerStream = await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});
    video.srcObject = scannerStream;
    status.textContent = scannerMode==='bula'
      ? 'Centralize o texto da bula dentro da moldura.'
      : 'Aponte para o código de barras ou a caixa do remédio.';
  }catch(e){
    status.textContent = 'Câmera indisponível — use a opção abaixo.';
  }
}
function stopScanner(){
  if(scannerStream){ scannerStream.getTracks().forEach(t=>t.stop()); scannerStream=null; }
}
function buildScannerMockList(){
  document.getElementById('scanner-mock-list').innerHTML = ALL_MEDS.slice(0,6).map(m=>
    `<button class="chip" onclick="scanResult(${m.id})">${m.name.split(' ')[0]}</button>`
  ).join('');
}

/* botão "Capturar agora" muda de comportamento conforme o modo escolhido */
function mockCapture(){
  if(scannerMode==='bula'){ captureBulaFrame(); return; }
  if(ALL_MEDS.length===0) return;
  const med = ALL_MEDS[Math.floor(Math.random()*ALL_MEDS.length)];
  scanResult(med.id);
}
function scanResult(medId){
  const med = ALL_MEDS.find(m=>m.id===medId);
  if(!med) return;
  showToast(`Identificado: ${med.name}`);
  switchTab('home');
  document.getElementById('search-input').value = med.name;
  setCat('Todos');
  renderResults();
}

/* ---- leitura de bula (OCR real, via Tesseract.js carregado sob demanda) ---- */
let tesseractLoadPromise = null;
function loadTesseract(){
  if(window.Tesseract) return Promise.resolve();
  if(tesseractLoadPromise) return tesseractLoadPromise;
  tesseractLoadPromise = new Promise((resolve, reject)=>{
    const script = document.createElement('script');
    script.src = 'https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js';
    script.onload = resolve;
    script.onerror = ()=> reject(new Error('Não foi possível carregar o leitor de texto (é preciso estar conectado à internet).'));
    document.head.appendChild(script);
  });
  return tesseractLoadPromise;
}

function captureBulaFrame(){
  const video = document.getElementById('scanner-video');
  if(!video.videoWidth){ showToast('Aguarde a câmera carregar e tente de novo.'); return; }
  const canvas = document.getElementById('scanner-canvas');
  canvas.width = video.videoWidth;
  canvas.height = video.videoHeight;
  canvas.getContext('2d').drawImage(video, 0, 0);
  runBulaOcr(canvas);
}

async function runBulaOcr(canvasOrText){
  document.getElementById('scanner-camera-step').classList.add('hidden');
  document.getElementById('scanner-bula-result').classList.remove('hidden');
  document.getElementById('bula-loading').classList.remove('hidden');
  document.getElementById('bula-content').innerHTML = '';
  stopScanner();

  try{
    await loadTesseract();
    const { data } = await window.Tesseract.recognize(canvasOrText, 'por');
    renderBulaResult(data.text);
  }catch(e){
    document.getElementById('bula-loading').classList.add('hidden');
    document.getElementById('bula-content').innerHTML = `
      <div class="bula-warning">Não foi possível ler o texto da foto (${e.message}). Tente novamente com mais luz, ou cole o texto manualmente.</div>`;
  }
}

/* usado pelo botão de colar texto manualmente (sem precisar de câmera/OCR) */
function processBulaText(text){
  if(!text || !text.trim()){ showToast('Cole o texto da bula primeiro.'); return; }
  document.getElementById('scanner-camera-step').classList.add('hidden');
  document.getElementById('scanner-bula-result').classList.remove('hidden');
  document.getElementById('bula-loading').classList.add('hidden');
  renderBulaResult(text);
}

/* organiza o texto bruto da bula em seções simples e fáceis de ler */
const BULA_SECTIONS = [
  { key: 'contraindicacoes', label: 'Quando não usar', icon: '🚫', match: /contraindica[cç][õo]es|n[ãa]o devo usar/i },
  { key: 'indicacoes', label: 'Para que serve', icon: '💊', match: /para que (serve|é indicado)|indica[cç][õo]es/i },
  { key: 'como_usar', label: 'Como usar', icon: '⏰', match: /como (devo )?usar|posologia|modo de usar/i },
  { key: 'advertencias', label: 'Cuidados e advertências', icon: '⚠️', match: /advert[êe]ncias|precau[cç][õo]es|cuidados/i },
  { key: 'reacoes', label: 'Possíveis reações', icon: '🩹', match: /rea[cç][õo]es adversas|efeitos colaterais/i },
  { key: 'superdose', label: 'Em caso de uso a mais do que o indicado', icon: '🆘', match: /superdose|overdose/i },
];
function renderBulaResult(rawText){
  document.getElementById('bula-loading').classList.add('hidden');
  const text = (rawText||'').replace(/\r/g,'').replace(/[ \t]+/g,' ').trim();
  const wrap = document.getElementById('bula-content');

  if(text.length < 15){
    wrap.innerHTML = `<div class="bula-warning">O texto reconhecido ficou muito curto ou ilegível. Tente tirar a foto com mais luz e sem dobras, ou cole o texto manualmente.</div>`;
    return;
  }

  const lines = text.split('\n').map(l=>l.trim()).filter(Boolean);
  const found = [];
  let current = { label: 'Texto reconhecido', icon: '📄', body: [] };
  for(const line of lines){
    const section = BULA_SECTIONS.find(s=>s.match.test(line) && line.length < 80);
    if(section){
      if(current.body.length) found.push(current);
      current = { label: section.label, icon: section.icon, body: [] };
    } else {
      current.body.push(line);
    }
  }
  if(current.body.length) found.push(current);

  wrap.innerHTML = `
    <div class="bula-warning">⚠️ Leitura simplificada por reconhecimento de texto — pode conter erros. Sempre confira a bula impressa original antes de usar o medicamento, e consulte um farmacêutico ou médico em caso de dúvida.</div>
    ${found.map(s=>`
      <div class="bula-section">
        <h4>${s.icon} ${s.label}</h4>
        <p>${s.body.join(' ')}</p>
      </div>
    `).join('')}
  `;
}

/* ============================================================
   CALENDÁRIO / LEMBRETES
   ============================================================ */
const DOW = ['D','S','T','Q','Q','S','S'];
const MONTHS = ['Janeiro','Fevereiro','Março','Abril','Maio','Junho','Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'];

function calShiftMonth(delta){
  state.calMonth += delta;
  if(state.calMonth<0){ state.calMonth=11; state.calYear--; }
  if(state.calMonth>11){ state.calMonth=0; state.calYear++; }
  renderCalendar();
}

async function renderCalendar(){
  document.getElementById('cal-month-label').textContent = `${MONTHS[state.calMonth]} ${state.calYear}`;
  try{
    const data = await apiFetch('/api/reminders');
    state.reminders = data.reminders.map(r=>({id:r.id, med:r.med_name, time:r.time, day:r.day, month:r.month, year:r.year}));
  }catch(e){ /* mantém o que já tinha em memória */ }

  const grid = document.getElementById('cal-grid');
  const firstDow = new Date(state.calYear, state.calMonth, 1).getDay();
  const daysInMonth = new Date(state.calYear, state.calMonth+1, 0).getDate();
  let html = DOW.map(d=>`<div class="cal-dow">${d}</div>`).join('');
  for(let i=0;i<firstDow;i++) html += `<div class="cal-day muted"></div>`;
  for(let d=1; d<=daysInMonth; d++){
    const hasRem = state.reminders.some(r=> r.day===d && r.month===state.calMonth && r.year===state.calYear);
    const sel = state.calSelectedDay===d;
    html += `<div class="cal-day ${sel?'selected':''} ${hasRem?'has-rem':''}" onclick="calSelectDay(${d})">${d}</div>`;
  }
  grid.innerHTML = html;
  renderReminderList();
}
function calSelectDay(d){ state.calSelectedDay = d; renderCalendar(); }

async function addReminder(){
  const med = document.getElementById('rem-med').value.trim();
  const time = document.getElementById('rem-time').value;
  if(!med || !time){ showToast('Preencha o remédio e o horário.'); return; }
  try{
    await apiFetch('/api/reminders', {method:'POST', body: JSON.stringify({
      medName: med, time, day: state.calSelectedDay, month: state.calMonth, year: state.calYear
    })});
    document.getElementById('rem-med').value='';
    await renderCalendar();
    showToast('Lembrete definido com sucesso!');
  }catch(e){
    showToast(e.message);
  }
}
async function removeReminder(id){
  try{
    await apiFetch(`/api/reminders/${id}`, {method:'DELETE'});
    await renderCalendar();
  }catch(e){
    showToast(e.message);
  }
}
function renderReminderList(){
  const list = state.reminders
    .filter(r=>r.month===state.calMonth && r.year===state.calYear)
    .sort((a,b)=> a.day-b.day || a.time.localeCompare(b.time));
  const el = document.getElementById('rem-list');
  if(list.length===0){ el.innerHTML = `<div class="empty-state" style="padding:24px 10px;"><p>Nenhum lembrete este mês ainda.</p></div>`; return; }
  el.innerHTML = list.map(r=>`
    <div class="rem-item">
      <div class="rem-time">${r.time}</div>
      <div class="rem-info"><p>${r.med}</p><span>Dia ${r.day} de ${MONTHS[r.month]}</span></div>
      <button class="rem-del" onclick="removeReminder(${r.id})"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 6h18M8 6V4a1 1 0 011-1h6a1 1 0 011 1v2m2 0v14a1 1 0 01-1 1H7a1 1 0 01-1-1V6h12z"/></svg></button>
    </div>
  `).join('');
}

